insert into public.quiz_questions (question, options, correct_index, explanation, reference, category, difficulty) values
('Which is the first book of the Bible?', '["Exodus", "Genesis", "Psalms", "Matthew"]'::jsonb, 1, 'Genesis means ''beginnings'' and opens the Scriptures.', 'Genesis 1:1', 'Bible Basics', 'easy'),
('Which is the last book of the Bible?', '["Jude", "Acts", "Revelation", "Malachi"]'::jsonb, 2, 'Revelation closes the canon with the unveiling of Jesus Christ.', 'Revelation 22:21', 'Bible Basics', 'easy'),
('How many books are in the New Testament?', '["27", "39", "12", "66"]'::jsonb, 0, 'The New Testament has 27 books.', '-', 'Bible Basics', 'medium'),
('How many books are in the Old Testament?', '["27", "39", "40", "50"]'::jsonb, 1, 'The Old Testament has 39 books.', '-', 'Bible Basics', 'medium'),
('The first four books of the New Testament are called the...', '["Epistles", "Gospels", "Prophets", "Law"]'::jsonb, 1, 'Matthew, Mark, Luke and John are the four Gospels.', '-', 'Bible Basics', 'easy'),
('Which book records the history of the early Christian church?', '["Romans", "Acts", "Hebrews", "James"]'::jsonb, 1, 'The book of Acts records the apostles and the early church.', 'Acts 1', 'Bible Basics', 'easy'),
('Most of the Psalms were written by whom?', '["Moses", "Solomon", "David", "Asaph"]'::jsonb, 2, 'David, the shepherd-king, wrote many of the Psalms.', '-', 'Bible Basics', 'medium'),
('Which book is a collection of wise sayings, mostly by Solomon?', '["Proverbs", "Job", "Ruth", "Ezra"]'::jsonb, 0, 'Proverbs gathers wisdom for daily living.', 'Proverbs 1:1', 'Bible Basics', 'easy'),
('The first five books of the Bible are known as the...', '["Gospels", "Pentateuch", "Prophets", "Writings"]'::jsonb, 1, 'The Pentateuch (Torah) - the five books of Moses.', '-', 'Bible Basics', 'medium'),
('What is the shortest verse in the English Bible?', '["''God is love.''", "''Pray always.''", "''Jesus wept.''", "''Rejoice always.''"]'::jsonb, 2, '''Jesus wept'' - at the tomb of Lazarus.', 'John 11:35', 'Bible Basics', 'medium'),
('Who wrote many of the New Testament letters (epistles)?', '["Peter", "Paul", "John", "Luke"]'::jsonb, 1, 'The apostle Paul wrote many epistles to the churches.', '-', 'Bible Basics', 'easy'),
('How many books are in the whole Protestant Bible?', '["66", "73", "39", "27"]'::jsonb, 0, '39 Old + 27 New = 66 books.', '-', 'Bible Basics', 'easy'),
('Who built the ark to survive the flood?', '["Abraham", "Noah", "Moses", "Enoch"]'::jsonb, 1, 'Noah built the ark by faith at God''s command.', 'Genesis 6', 'Bible Characters', 'easy'),
('Who led the Israelites out of Egypt?', '["Joshua", "Aaron", "Moses", "Caleb"]'::jsonb, 2, 'God used Moses to deliver Israel from Egyptian bondage.', 'Exodus 12', 'Bible Characters', 'easy'),
('Which strong man''s strength was in his uncut hair?', '["Samson", "Gideon", "Saul", "Goliath"]'::jsonb, 0, 'Samson, a Nazirite judge, lost his strength when his hair was cut.', 'Judges 16', 'Bible Characters', 'easy'),
('Who defeated the giant Goliath with a sling and stone?', '["Jonathan", "David", "Saul", "Samuel"]'::jsonb, 1, 'Young David trusted God and felled Goliath.', '1 Samuel 17', 'Bible Characters', 'easy'),
('Who was thrown into the lions'' den for praying?', '["Daniel", "Joseph", "Jeremiah", "Ezekiel"]'::jsonb, 0, 'Daniel kept praying and God shut the lions'' mouths.', 'Daniel 6', 'Bible Characters', 'easy'),
('Who interpreted Pharaoh''s dreams and saved Egypt from famine?', '["Moses", "Joseph", "Daniel", "Jacob"]'::jsonb, 1, 'Joseph, sold by his brothers, rose to rule Egypt.', 'Genesis 41', 'Bible Characters', 'medium'),
('Who was swallowed by a great fish?', '["Jonah", "Job", "Hosea", "Amos"]'::jsonb, 0, 'Jonah fled from God and was swallowed by a great fish.', 'Jonah 1-2', 'Bible Characters', 'easy'),
('Who built the first temple in Jerusalem?', '["David", "Solomon", "Hezekiah", "Josiah"]'::jsonb, 1, 'Solomon built the temple his father David had planned.', '1 Kings 6', 'Bible Characters', 'medium'),
('Who is called the father of the faithful and friend of God?', '["Noah", "Abraham", "Isaac", "Jacob"]'::jsonb, 1, 'Abraham believed God and it was counted to him as righteousness.', 'Romans 4; James 2:23', 'Bible Characters', 'medium'),
('Who led Israel into the Promised Land after Moses died?', '["Caleb", "Joshua", "Aaron", "Gideon"]'::jsonb, 1, 'Joshua led Israel across the Jordan into Canaan.', 'Joshua 1', 'Bible Characters', 'medium'),
('The three Hebrews thrown into the fiery furnace were Shadrach, Meshach and...', '["Abednego", "Daniel", "Nebuchadnezzar", "Belshazzar"]'::jsonb, 0, 'They refused to bow to the image and God preserved them.', 'Daniel 3', 'Bible Characters', 'medium'),
('Whose wife became a pillar of salt looking back at Sodom?', '["Abraham''s", "Lot''s", "Isaac''s", "Noah''s"]'::jsonb, 1, 'Lot''s wife looked back and became a pillar of salt.', 'Genesis 19:26', 'Bible Characters', 'medium'),
('Who was the first man God created?', '["Cain", "Abel", "Adam", "Seth"]'::jsonb, 2, 'God formed Adam from the dust of the ground.', 'Genesis 2:7', 'Bible Characters', 'easy'),
('Who was taken to heaven in a whirlwind without dying?', '["Enoch", "Elijah", "Moses", "Isaiah"]'::jsonb, 1, 'Elijah was taken up in a chariot of fire.', '2 Kings 2:11', 'Bible Characters', 'medium'),
('Who baptized Jesus in the Jordan River?', '["Peter", "John the Baptist", "Andrew", "Philip"]'::jsonb, 1, 'John the Baptist baptized Jesus, and the Spirit descended as a dove.', 'Matthew 3:13-16', 'Bible Characters', 'easy'),
('Who betrayed Jesus for thirty pieces of silver?', '["Peter", "Thomas", "Judas Iscariot", "John"]'::jsonb, 2, 'Judas betrayed Jesus with a kiss.', 'Matthew 26:14-16', 'Bible Characters', 'easy'),
('Which disciple denied Jesus three times?', '["John", "Peter", "James", "Andrew"]'::jsonb, 1, 'Peter denied Jesus before the rooster crowed, then wept bitterly.', 'Luke 22:54-62', 'Bible Characters', 'easy'),
('Who was the mother of Jesus?', '["Martha", "Mary", "Elizabeth", "Anna"]'::jsonb, 1, 'Mary was chosen to be the mother of Jesus.', 'Luke 1:30-31', 'Bible Characters', 'easy'),
('The persecutor Saul became which apostle after meeting Jesus?', '["Peter", "Paul", "Barnabas", "Silas"]'::jsonb, 1, 'Saul of Tarsus became Paul, apostle to the Gentiles.', 'Acts 9', 'Bible Characters', 'medium'),
('Which short tax collector climbed a tree to see Jesus?', '["Matthew", "Zacchaeus", "Levi", "Nicodemus"]'::jsonb, 1, 'Zacchaeus climbed a sycamore tree and Jesus came to his house.', 'Luke 19:1-10', 'Bible Characters', 'medium'),
('Whom did Jesus raise after four days in the tomb?', '["Jairus'' daughter", "Lazarus", "The widow''s son", "Dorcas"]'::jsonb, 1, 'Jesus called Lazarus out of the grave.', 'John 11', 'Bible Characters', 'medium'),
('Which disciple doubted until he saw Jesus'' wounds?', '["Thomas", "Philip", "Nathanael", "James"]'::jsonb, 0, '''Doubting'' Thomas believed when he saw the risen Christ.', 'John 20:24-29', 'Bible Characters', 'medium'),
('Who was the first Christian martyr, stoned for his faith?', '["Stephen", "James", "Paul", "Peter"]'::jsonb, 0, 'Stephen was stoned while seeing heaven opened.', 'Acts 7', 'Bible Characters', 'hard'),
('Which Roman governor sentenced Jesus to be crucified?', '["Herod", "Pontius Pilate", "Felix", "Festus"]'::jsonb, 1, 'Pilate washed his hands yet delivered Jesus to be crucified.', 'Matthew 27', 'Bible Characters', 'medium'),
('In which town was Jesus born?', '["Nazareth", "Bethlehem", "Jerusalem", "Capernaum"]'::jsonb, 1, 'Jesus was born in Bethlehem, as prophesied.', 'Micah 5:2; Luke 2', 'Gospels', 'easy'),
('How many disciples did Jesus choose?', '["Seven", "Ten", "Twelve", "Seventy"]'::jsonb, 2, 'Jesus chose twelve apostles.', 'Mark 3:14', 'Gospels', 'easy'),
('Jesus fed five thousand with five loaves and how many fish?', '["One", "Two", "Three", "Five"]'::jsonb, 1, 'Five loaves and two fish fed the multitude with leftovers.', 'John 6:1-13', 'Gospels', 'medium'),
('On what did Jesus ride into Jerusalem?', '["A horse", "A donkey/colt", "A camel", "On foot"]'::jsonb, 1, 'Jesus rode a donkey''s colt, fulfilling prophecy.', 'Zechariah 9:9; Matthew 21', 'Gospels', 'medium'),
('How many days was Jesus tempted in the wilderness?', '["Three", "Seven", "Forty", "Fifty"]'::jsonb, 2, 'Jesus fasted forty days and overcame temptation by the Word.', 'Matthew 4:1-11', 'Gospels', 'medium'),
('What model prayer did Jesus teach His disciples?', '["The Shema", "The Lord''s Prayer", "The Sinner''s Prayer", "The Psalter"]'::jsonb, 1, 'The Lord''s Prayer begins ''Our Father in heaven...''', 'Matthew 6:9-13', 'Gospels', 'easy'),
('Where did Jesus give the Beatitudes?', '["The Sermon on the Mount", "The temple", "The upper room", "The Mount of Olives"]'::jsonb, 0, '''Blessed are...'' opens the Sermon on the Mount.', 'Matthew 5', 'Gospels', 'medium'),
('Who appeared with Jesus at the Transfiguration?', '["Abraham and Isaac", "Moses and Elijah", "David and Solomon", "Peter and John"]'::jsonb, 1, 'Moses and Elijah talked with Jesus on the mountain.', 'Matthew 17:1-3', 'Gospels', 'hard'),
('From which place did Jesus ascend to heaven?', '["Mount Sinai", "The Mount of Olives", "Mount Carmel", "Golgotha"]'::jsonb, 1, 'Jesus ascended from the Mount of Olives near Bethany.', 'Acts 1:9-12', 'Gospels', 'medium'),
('What happened on the third day after Jesus'' crucifixion?', '["His ascension", "His resurrection", "Pentecost", "His trial"]'::jsonb, 1, 'Jesus rose from the dead on the third day.', 'Luke 24:1-7', 'Gospels', 'easy'),
('The parable of the lost son is also known as the parable of the...', '["Good Samaritan", "Prodigal Son", "Sower", "Talents"]'::jsonb, 1, 'The Prodigal Son returns to a forgiving father - a picture of God''s grace.', 'Luke 15:11-32', 'Parables', 'easy'),
('In the parable of the Good Samaritan, who helped the wounded man?', '["A priest", "A Levite", "A Samaritan", "A scribe"]'::jsonb, 2, 'A despised Samaritan showed mercy, teaching who our neighbour is.', 'Luke 10:25-37', 'Parables', 'medium'),
('The parable of the sower is about seed falling on different...', '["mountains", "soils/hearts", "seasons", "rivers"]'::jsonb, 1, 'The seed is the Word; the soils are the hearts that receive it.', 'Matthew 13:3-23', 'Parables', 'medium'),
('In the parable of the ten virgins, how many were wise?', '["Three", "Five", "Seven", "Ten"]'::jsonb, 1, 'Five wise virgins had oil and were ready for the bridegroom.', 'Matthew 25:1-13', 'Parables', 'medium'),
('In the parable of the lost sheep, how many sheep did the shepherd leave to seek one?', '["9", "49", "99", "100"]'::jsonb, 2, 'The shepherd left ninety-nine to find the one that was lost.', 'Luke 15:3-7', 'Parables', 'medium'),
('Which of the Ten Commandments is about the Sabbath?', '["The third", "The fourth", "The fifth", "The seventh"]'::jsonb, 1, 'The fourth commandment - ''Remember the Sabbath day, to keep it holy.''', 'Exodus 20:8-11', 'Sabbath', 'medium'),
('The Sabbath is a memorial of what event?', '["The Exodus", "Creation", "The Cross", "Pentecost"]'::jsonb, 1, 'The Sabbath memorialises God''s creation in six days and rest on the seventh.', 'Genesis 2:1-3; Exodus 20:11', 'Sabbath', 'medium'),
('Jesus said the Sabbath was made for whom?', '["Priests", "Israel only", "Man", "Angels"]'::jsonb, 2, '''The Sabbath was made for man, not man for the Sabbath.''', 'Mark 2:27', 'Sabbath', 'medium'),
('When does the biblical Sabbath begin and end?', '["Midnight to midnight", "Sunrise to sunrise", "Sunset to sunset", "Noon to noon"]'::jsonb, 2, '''From even unto even shall ye celebrate your sabbath.''', 'Leviticus 23:32', 'Sabbath', 'medium'),
('Who did Jesus say is Lord of the Sabbath?', '["Moses", "The Son of Man (Jesus)", "The priests", "David"]'::jsonb, 1, '''The Son of Man is Lord even of the Sabbath.''', 'Matthew 12:8', 'Sabbath', 'medium'),
('In Daniel 2, the chest and arms of silver represented which kingdom?', '["Babylon", "Medo-Persia", "Greece", "Rome"]'::jsonb, 1, 'Silver represented Medo-Persia, which followed Babylon.', 'Daniel 2:39', 'Prophecy', 'hard'),
('In Daniel 2, the belly and thighs of bronze represented...', '["Greece", "Egypt", "Rome", "Assyria"]'::jsonb, 0, 'Bronze represented Greece under Alexander.', 'Daniel 2:39', 'Prophecy', 'hard'),
('In Daniel 2, the legs of iron represented which empire?', '["Greece", "Rome", "Babylon", "Persia"]'::jsonb, 1, 'Iron represented Rome, strong and crushing.', 'Daniel 2:40', 'Prophecy', 'hard'),
('In Daniel 2, the stone cut without hands that destroyed the image represents...', '["A great king", "God''s everlasting kingdom", "The church of Rome", "Babylon"]'::jsonb, 1, 'The stone is God''s kingdom that will fill the whole earth.', 'Daniel 2:44-45', 'Prophecy', 'medium'),
('What is the number of the beast in Revelation?', '["616", "666", "777", "144"]'::jsonb, 1, '''His number is six hundred threescore and six.''', 'Revelation 13:18', 'Prophecy', 'easy'),
('Babylon in the book of Revelation symbolises...', '["A literal city only", "False or apostate religion", "Modern Iraq", "The Roman army"]'::jsonb, 1, 'Babylon symbolises confused, false religion opposed to God''s truth.', 'Revelation 17-18', 'Prophecy', 'hard'),
('The first angel''s message of Revelation 14 calls people to fear God and...', '["build temples", "worship the Creator", "keep silent", "flee the cities"]'::jsonb, 1, 'It calls every nation to worship Him who made heaven and earth.', 'Revelation 14:7', 'Prophecy', 'medium'),
('How many churches are addressed in Revelation chapters 2 and 3?', '["Three", "Seven", "Ten", "Twelve"]'::jsonb, 1, 'Seven churches receive messages from Jesus.', 'Revelation 1:11', 'Prophecy', 'medium'),
('According to Paul, our body is the temple of the...', '["angels", "Holy Spirit", "law", "church"]'::jsonb, 1, 'Glorify God in your body, the temple of the Holy Spirit.', '1 Corinthians 6:19-20', 'Health', 'easy'),
('Daniel and his friends asked to eat what instead of the king''s rich food?', '["meat and wine", "vegetables and water", "bread only", "fish"]'::jsonb, 1, 'They ate pulse (vegetables) and water and were healthier.', 'Daniel 1:12-15', 'Health', 'medium'),
('''Whether you eat or drink, do all to the glory of...''', '["yourself", "God", "the church", "others"]'::jsonb, 1, 'All of life, including eating, should glorify God.', '1 Corinthians 10:31', 'Health', 'easy'),
('The health principle of ''temperance'' means...', '["eating a lot", "self-control / moderation", "fasting always", "skipping meals"]'::jsonb, 1, 'Temperance is self-control - moderation in good things, avoiding the harmful.', 'Galatians 5:23', 'Health', 'medium'),
('We are saved by grace through...', '["works", "faith", "law-keeping", "baptism alone"]'::jsonb, 1, 'By grace are you saved through faith - the gift of God.', 'Ephesians 2:8', 'Salvation', 'easy'),
('''For God so loved the world that He gave His only...''', '["angel", "prophet", "Son", "law"]'::jsonb, 2, 'God gave His only begotten Son so we might have eternal life.', 'John 3:16', 'Salvation', 'easy'),
('Who is our Mediator and High Priest before God?', '["Moses", "Mary", "Jesus", "The angels"]'::jsonb, 2, 'There is one Mediator between God and men, Christ Jesus.', '1 Timothy 2:5; Hebrews 8', 'Salvation', 'medium'),
('''If we confess our sins, He is faithful and just to...''', '["punish us", "forgive us", "forget us", "test us"]'::jsonb, 1, 'He forgives our sins and cleanses us from all unrighteousness.', '1 John 1:9', 'Salvation', 'easy'),
('Being ''born again'' is by water and the...', '["fire", "Spirit", "law", "word only"]'::jsonb, 1, '''Except a man be born of water and of the Spirit...''', 'John 3:5', 'Salvation', 'medium'),
('Repentance means...', '["feeling sad only", "turning from sin to God", "paying a fine", "doing penance"]'::jsonb, 1, 'Repentance is godly sorrow that leads to turning from sin.', 'Acts 3:19', 'Salvation', 'medium'),
('''You shall have no other gods before Me'' is which commandment?', '["First", "Second", "Third", "Fourth"]'::jsonb, 0, 'The first commandment - God alone is to be worshipped.', 'Exodus 20:3', 'Law', 'easy'),
('''You shall not steal'' is which commandment?', '["Sixth", "Seventh", "Eighth", "Ninth"]'::jsonb, 2, 'The eighth commandment forbids stealing.', 'Exodus 20:15', 'Law', 'medium'),
('The two great commandments are to love God and love your...', '["money", "neighbour", "nation", "self only"]'::jsonb, 1, 'Love God supremely and your neighbour as yourself.', 'Matthew 22:37-39', 'Law', 'easy'),
('The Ten Commandments appear in Exodus 20 and which other chapter?', '["Leviticus 19", "Deuteronomy 5", "Numbers 6", "Genesis 9"]'::jsonb, 1, 'They are repeated in Deuteronomy 5.', 'Deuteronomy 5', 'Law', 'hard'),
('''You shall not bear false witness'' forbids...', '["stealing", "lying", "coveting", "idolatry"]'::jsonb, 1, 'The ninth commandment forbids lying and false testimony.', 'Exodus 20:16', 'Law', 'medium'),
('Which Ellen White book describes the life of Christ?', '["The Great Controversy", "The Desire of Ages", "Steps to Christ", "Education"]'::jsonb, 1, '''The Desire of Ages'' is her classic on the life of Jesus.', '-', 'Spirit of Prophecy', 'medium'),
('Which Ellen White book covers the great controversy from Jerusalem to the new earth?', '["Patriarchs and Prophets", "The Great Controversy", "Education", "The Ministry of Healing"]'::jsonb, 1, '''The Great Controversy'' traces the conflict between Christ and Satan through history.', '-', 'Spirit of Prophecy', 'medium'),
('Which short Ellen White book guides a person in coming to Christ?', '["Steps to Christ", "Acts of the Apostles", "Prophets and Kings", "Christ''s Object Lessons"]'::jsonb, 0, '''Steps to Christ'' is a beloved guide to conversion and walking with God.', '-', 'Spirit of Prophecy', 'medium'),
('The gift of prophecy is listed among the spiritual...', '["talents", "gifts", "fruits", "laws"]'::jsonb, 1, 'Prophecy is one of the spiritual gifts given to the church.', '1 Corinthians 12; Ephesians 4:11', 'Spirit of Prophecy', 'medium'),
('''Pray without...''', '["doubting", "ceasing", "fasting", "boasting"]'::jsonb, 1, 'Believers are to pray continually.', '1 Thessalonians 5:17', 'Christian Living', 'easy'),
('The ''golden rule'' says: do to others as you would have them...', '["pay you", "do to you", "leave you", "follow you"]'::jsonb, 1, '''Do unto others as you would have them do unto you.''', 'Matthew 7:12', 'Christian Living', 'easy'),
('How many times did Jesus say we should forgive?', '["Seven times", "Seventy times seven", "Three times", "Once"]'::jsonb, 1, 'Forgive ''seventy times seven'' - without limit.', 'Matthew 18:21-22', 'Christian Living', 'medium'),
('The Bereans were commended because they searched the Scriptures...', '["once a year", "daily", "only on feast days", "rarely"]'::jsonb, 1, 'The Bereans searched the Scriptures daily to verify the message.', 'Acts 17:11', 'Christian Living', 'medium'),
('What is the first quality listed in the fruit of the Spirit?', '["Joy", "Peace", "Love", "Goodness"]'::jsonb, 2, '''The fruit of the Spirit is love, joy, peace...''', 'Galatians 5:22', 'Christian Living', 'easy'),
('Which relief agency was founded by the Adventist Church?', '["Red Cross", "ADRA", "UNICEF", "Caritas"]'::jsonb, 1, 'ADRA is the Adventist Development and Relief Agency.', '-', 'Adventist History', 'medium'),
('The first official Adventist missionary sent overseas was...', '["J. N. Andrews", "Joseph Bates", "James White", "Uriah Smith"]'::jsonb, 0, 'J. N. Andrews was sent to Europe in 1874.', '-', 'Adventist History', 'hard'),
('How often does the General Conference Session of the church meet?', '["Every year", "Every 5 years", "Every 10 years", "Every 2 years"]'::jsonb, 1, 'The world church meets in session every five years.', '-', 'Adventist History', 'hard'),
('Adventist education aims to develop the whole person - mental, physical and...', '["financial", "spiritual", "political", "social only"]'::jsonb, 1, 'True education develops the mental, physical and spiritual powers.', '-', 'Adventist History', 'medium'),
('The Adventist Church''s flagship magazine in North America is the...', '["Watchtower", "Adventist Review", "Liberty", "Signs"]'::jsonb, 1, 'The Adventist Review is the church''s flagship journal.', '-', 'Adventist History', 'medium'),
('Who was the high priest''s servant whose ear Peter cut off?', '["Malchus", "Barabbas", "Demas", "Lysias"]'::jsonb, 0, 'Peter cut off Malchus''s ear, and Jesus healed it.', 'John 18:10; Luke 22:51', 'Bible Characters', 'hard'),
('On the Day of Pentecost, what filled the believers?', '["Fear", "The Holy Spirit", "Sleep", "Doubt"]'::jsonb, 1, 'The Holy Spirit was poured out and the church was empowered.', 'Acts 2', 'Bible Basics', 'medium'),
('What sign did God give Noah after the flood?', '["A star", "A rainbow", "An altar", "A dove"]'::jsonb, 1, 'The rainbow is the sign of God''s covenant.', 'Genesis 9:13', 'Bible Characters', 'easy'),
('Who wrote the book of Revelation while exiled on Patmos?', '["Paul", "Peter", "John", "James"]'::jsonb, 2, 'The apostle John received the Revelation on the isle of Patmos.', 'Revelation 1:9', 'Bible Basics', 'medium'),
('What did God create on the first day?', '["Animals", "Light", "The sun", "Man"]'::jsonb, 1, '''Let there be light'' - God created light on the first day.', 'Genesis 1:3', 'Creation', 'easy'),
('On which day of creation did God make humankind?', '["Fourth", "Fifth", "Sixth", "Seventh"]'::jsonb, 2, 'God made man on the sixth day, then rested on the seventh.', 'Genesis 1:26-31', 'Creation', 'medium'),
('Communion (the Lord''s Supper) commemorates Jesus''...', '["birth", "death", "baptism", "ascension"]'::jsonb, 1, 'It memorialises Christ''s broken body and shed blood until He comes.', '1 Corinthians 11:23-26', 'Doctrine', 'medium'),
('What two emblems are used in the Lord''s Supper?', '["Bread and water", "Unleavened bread and unfermented wine", "Honey and oil", "Salt and bread"]'::jsonb, 1, 'Unleavened bread and the unfermented fruit of the vine.', 'Matthew 26:26-29', 'Doctrine', 'medium'),
('Spiritual gifts are given to the church for what purpose?', '["personal fame", "building up the body of Christ", "earning salvation", "ruling others"]'::jsonb, 1, 'Gifts are for the edifying of the church and its mission.', 'Ephesians 4:11-13', 'Doctrine', 'medium'),
('What did Jesus promise to send after returning to heaven?', '["An angel", "The Holy Spirit (Comforter)", "A prophet", "Riches"]'::jsonb, 1, 'Jesus promised the Comforter, the Holy Spirit.', 'John 14:16-17', 'Doctrine', 'medium'),
('Tithe in the Bible is a tenth that belongs to...', '["the priest", "the Lord", "the poor", "the king"]'::jsonb, 1, '''The tithe... is the Lord''s; it is holy unto the Lord.''', 'Leviticus 27:30', 'Stewardship', 'easy'),
('Beyond tithe, freewill gifts for God''s work are called...', '["taxes", "offerings", "fines", "dues"]'::jsonb, 1, 'Offerings are given freely above the tithe.', 'Malachi 3:8', 'Stewardship', 'medium'),
('Which feast did Jesus institute the Lord''s Supper during?', '["Pentecost", "Passover", "Tabernacles", "Purim"]'::jsonb, 1, 'Jesus instituted Communion during the Passover with His disciples.', 'Luke 22:7-20', 'Doctrine', 'hard'),
('After creation, why did God bless and sanctify the seventh day?', '["He was tired", "He rested and set it apart as holy", "To start a new week", "For the angels"]'::jsonb, 1, 'God rested, blessed and sanctified the seventh day.', 'Genesis 2:2-3', 'Sabbath', 'easy'),
('What happens to the righteous dead at Jesus'' second coming?', '["They stay asleep", "They are raised to immortal life", "They become angels", "They are judged then"]'::jsonb, 1, 'The dead in Christ rise first and are given immortality.', '1 Thessalonians 4:16; 1 Corinthians 15:51-54', 'Second Coming', 'medium'),
('Which prophet foretold Messiah would be born in Bethlehem?', '["Isaiah", "Micah", "Joel", "Nahum"]'::jsonb, 1, 'Micah prophesied the ruler would come from Bethlehem.', 'Micah 5:2', 'Prophecy', 'hard'),
('''The just shall live by...''', '["works", "faith", "law", "sight"]'::jsonb, 1, 'A key text of the Reformation - the just live by faith.', 'Romans 1:17; Habakkuk 2:4', 'Salvation', 'medium'),
('Who was the apostle known as a physician who wrote a Gospel and Acts?', '["Mark", "Luke", "Matthew", "John"]'::jsonb, 1, 'Luke, the beloved physician, wrote Luke and Acts.', 'Colossians 4:14', 'Bible Basics', 'hard'),
('Which mountain did Elijah confront the prophets of Baal on?', '["Sinai", "Carmel", "Horeb", "Tabor"]'::jsonb, 1, 'On Mount Carmel, fire fell and proved the Lord is God.', '1 Kings 18', 'Bible Characters', 'hard'),
('How many people were saved in the ark during the flood?', '["Two", "Four", "Eight", "Twelve"]'::jsonb, 2, 'Noah, his wife, three sons and their wives - eight in all.', '1 Peter 3:20', 'Bible Characters', 'medium'),
('What did Jesus say are the two greatest commandments rooted in?', '["fear", "love", "law", "tradition"]'::jsonb, 1, 'Love to God and love to man fulfil the law.', 'Matthew 22:40', 'Law', 'easy'),
('The seal of God in Revelation is contrasted with the mark of the...', '["dragon", "beast", "false prophet", "harlot"]'::jsonb, 1, 'Those sealed by God reject the mark of the beast.', 'Revelation 7:3; 14:9', 'Prophecy', 'medium'),
('Which Old Testament book tells of a faithful woman who gleaned in Boaz''s field?', '["Esther", "Ruth", "Judith", "Hannah"]'::jsonb, 1, 'Ruth, a Moabite, became an ancestor of David and of Christ.', 'Ruth 2', 'Bible Characters', 'medium'),
('Who was the queen who risked her life to save her people, the Jews?', '["Esther", "Vashti", "Deborah", "Bathsheba"]'::jsonb, 0, 'Queen Esther interceded for the Jews - ''for such a time as this.''', 'Esther 4:14', 'Bible Characters', 'medium'),
('Which judge defeated the Midianites with only 300 men?', '["Samson", "Gideon", "Ehud", "Barak"]'::jsonb, 1, 'Gideon''s 300 routed Midian by God''s power.', 'Judges 7', 'Bible Characters', 'hard'),
('What did God use to guide Israel by night in the wilderness?', '["A star", "A pillar of fire", "An angel walking", "The moon"]'::jsonb, 1, 'A pillar of cloud by day and fire by night.', 'Exodus 13:21', 'Bible Characters', 'medium'),
('Who wrote, ''I can do all things through Christ who strengthens me''?', '["David", "Paul", "Peter", "John"]'::jsonb, 1, 'Paul wrote this from prison to the Philippians.', 'Philippians 4:13', 'Bible Basics', 'medium');
